package com.taskly.recruitment;
import jakarta.validation.constraints.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
@Service
public class RecruitmentOfficeService {
 public record SlotWrite(@NotBlank @Size(max=160) String name,@NotBlank @Size(max=500) String address,@NotNull Instant startsAt,@Min(1) @Max(1000) int capacity,boolean active,@PositiveOrZero long version) {}
 public record AppointmentWrite(@NotNull UUID slotId,@NotBlank @Size(max=100) String requestId) {}
 public record Checkin(@NotBlank String code) {}
 public List<Map<String,Object>> offices(){return db.queryForList("SELECT DISTINCT name,address FROM partner_office_slots WHERE active=true ORDER BY name,address");}
 @Transactional public Map<String,Object> confirmVisit(UUID user){var app=recruitment.current(user);if(!Boolean.TRUE.equals(app.eligibility().get("preliminary_approved"))||!Boolean.TRUE.equals(app.eligibility().get("uniform_ordered")))throw RecruitmentService.invalid("Hoàn tất thủ tục chọn đồng phục trước khi xác nhận đến văn phòng.");if(db.queryForObject("SELECT COUNT(*) FROM recruitment_audit WHERE application_id=? AND action='OFFICE_VISIT_CONFIRMED'",Integer.class,app.id())==0)recruitment.audit(user,app.id(),"OFFICE_VISIT_CONFIRMED",app.status(),app.status(),"Partner đã xem địa chỉ và xác nhận sẽ đến văn phòng.");return Map.of("confirmed",true);}
 @Transactional public Map<String,Object> confirmCheckin(UUID actor,UUID applicationId){
  var app=recruitment.detail(applicationId);
  app=recruitment.current(app.userId());
  if(!Boolean.TRUE.equals(app.eligibility().get("preliminary_approved"))||!Set.of("PRELIMINARY_APPROVED","UNIFORM_PENDING","DOCUMENT_APPOINTMENT","ACTION_REQUIRED","DOCUMENTS_RECEIVED","FINAL_REVIEW").contains(app.status()))throw RecruitmentService.invalid("Hồ sơ chưa ở bước tiếp nhận tại văn phòng.");
  var existing=db.queryForList("SELECT * FROM partner_office_appointments WHERE application_id=? AND status IN ('BOOKED','CHECKED_IN','COMPLETED') ORDER BY created_at DESC LIMIT 1",applicationId);
  if(!existing.isEmpty()){
   var appointment=existing.getFirst();
   if(Boolean.TRUE.equals(app.eligibility().get("appointment_checked_in")))return appointment;
   return checkin(actor,(UUID)appointment.get("id"),new Checkin((String)appointment.get("checkin_code")));
  }
  var now=Timestamp.from(Instant.now());var slot=UUID.randomUUID();var appointment=UUID.randomUUID();
  db.update("INSERT INTO partner_office_slots VALUES(?,?,?,?,1,false,0)",slot,"Tiếp nhận trực tiếp tại văn phòng","Văn phòng dịch vụ TaskLy",now);
  db.update("INSERT INTO partner_office_appointments(id,application_id,slot_id,status,checkin_code,request_key,created_at) VALUES(?,?,?,'BOOKED',?,?,?)",appointment,applicationId,slot,UUID.randomUUID().toString().substring(0,18),"ADMIN_CHECKIN_"+appointment,now);
  return checkin(actor,appointment,new Checkin(db.queryForObject("SELECT checkin_code FROM partner_office_appointments WHERE id=?",String.class,appointment)));
 }
 public record ChecklistWrite(@NotBlank @Size(max=200) String label,boolean required,boolean active) {}
 public record Receive(@NotEmpty @Size(max=30) Map<UUID,Boolean> checklist,boolean originalsReturned,@NotBlank @Size(max=1000) String notes) {}
 private final JdbcTemplate db;private final RecruitmentService recruitment;private final RecruitmentReviewService review;private final ObjectMapper json=new ObjectMapper();
 public RecruitmentOfficeService(JdbcTemplate db,RecruitmentService recruitment,RecruitmentReviewService review){this.db=db;this.recruitment=recruitment;this.review=review;}
 private void lockApplicant(UUID appointment){var users=db.queryForList("SELECT p.user_id FROM partner_applications p JOIN partner_office_appointments a ON a.application_id=p.id WHERE a.id=?",UUID.class,appointment);if(users.isEmpty())throw RecruitmentService.invalid("Không tìm thấy lịch.");recruitment.current(users.getFirst());}
 public List<Map<String,Object>> slots(){return db.queryForList("SELECT s.*,s.capacity-(SELECT COUNT(*) FROM partner_office_appointments a WHERE a.slot_id=s.id AND a.status IN ('BOOKED','CHECKED_IN')) AS remaining FROM partner_office_slots s WHERE active=true AND starts_at>? ORDER BY starts_at",Timestamp.from(Instant.now()));}
 @Transactional public Map<String,Object> saveSlot(UUID actor,UUID id,SlotWrite w){if(!w.startsAt().isAfter(Instant.now()))throw RecruitmentService.invalid("Lịch hẹn phải ở tương lai.");var count=db.queryForObject("SELECT COUNT(*) FROM partner_office_appointments WHERE slot_id=? AND status IN ('BOOKED','CHECKED_IN')",Integer.class,id);if(w.capacity()<count)throw RecruitmentService.invalid("Sức chứa nhỏ hơn số lịch đã đặt.");if(db.queryForObject("SELECT COUNT(*) FROM partner_office_slots WHERE id=?",Integer.class,id)>0){if(db.update("UPDATE partner_office_slots SET name=?,address=?,starts_at=?,capacity=?,active=?,version=version+1 WHERE id=? AND version=?",w.name(),w.address(),Timestamp.from(w.startsAt()),w.capacity(),w.active(),id,w.version())!=1)throw RecruitmentService.conflict();}else db.update("INSERT INTO partner_office_slots VALUES(?,?,?,?,?,?,0)",id,w.name(),w.address(),Timestamp.from(w.startsAt()),w.capacity(),w.active());recruitment.audit(actor,null,"OFFICE_SLOT_UPDATED",null,null,"Lịch "+id);return db.queryForMap("SELECT * FROM partner_office_slots WHERE id=?",id);}
 public List<Map<String,Object>> appointments(UUID user){var a=recruitment.current(user);return db.queryForList("SELECT a.*,s.name,s.address,s.starts_at FROM partner_office_appointments a JOIN partner_office_slots s ON s.id=a.slot_id WHERE a.application_id=? ORDER BY a.created_at DESC",a.id());}
 public List<Map<String,Object>> queue(){return db.queryForList("SELECT a.*,s.name,s.address,s.starts_at FROM partner_office_appointments a JOIN partner_office_slots s ON s.id=a.slot_id ORDER BY s.starts_at DESC LIMIT 200");}
 @Transactional public Map<String,Object> book(UUID user,AppointmentWrite w){var app=recruitment.current(user);if(!app.eligibility().get("preliminary_approved"))throw RecruitmentService.invalid("Cần được duyệt sơ bộ trước khi đặt lịch.");var prior=db.queryForList("SELECT * FROM partner_office_appointments WHERE application_id=? AND request_key=?",app.id(),w.requestId());if(!prior.isEmpty()){if(!prior.getFirst().get("slot_id").equals(w.slotId()))throw RecruitmentService.conflict();return prior.getFirst();}if(!Set.of("PRELIMINARY_APPROVED","UNIFORM_PENDING","DOCUMENT_APPOINTMENT","ACTION_REQUIRED").contains(app.status()))throw RecruitmentService.invalid("Hồ sơ không ở bước đặt lịch hoặc bổ sung giấy tờ.");if(db.queryForObject("SELECT COUNT(*) FROM partner_office_appointments WHERE application_id=? AND status IN ('BOOKED','CHECKED_IN')",Integer.class,app.id())>0)throw RecruitmentService.invalid("Hủy lịch hiện tại trước khi đổi lịch.");var slots=db.queryForList("SELECT * FROM partner_office_slots WHERE id=? AND active=true AND starts_at>? FOR UPDATE",w.slotId(),Timestamp.from(Instant.now()));if(slots.isEmpty())throw RecruitmentService.invalid("Lịch không còn mở.");var row=slots.getFirst();if(db.queryForObject("SELECT COUNT(*) FROM partner_office_appointments WHERE slot_id=? AND status IN ('BOOKED','CHECKED_IN')",Integer.class,w.slotId())>=((Number)row.get("capacity")).intValue())throw RecruitmentService.invalid("Khung giờ đã hết chỗ.");var id=UUID.randomUUID();db.update("INSERT INTO partner_office_appointments(id,application_id,slot_id,status,checkin_code,request_key,created_at) VALUES(?,?,?,'BOOKED',?,?,?)",id,app.id(),w.slotId(),UUID.randomUUID().toString().substring(0,8).toUpperCase(),w.requestId(),Timestamp.from(Instant.now()));db.update("UPDATE partner_applications SET status='DOCUMENT_APPOINTMENT',version=version+1,updated_at=? WHERE id=?",Timestamp.from(Instant.now()),app.id());recruitment.audit(user,app.id(),"OFFICE_APPOINTMENT_BOOKED",app.status(),"DOCUMENT_APPOINTMENT","");return db.queryForMap("SELECT * FROM partner_office_appointments WHERE id=?",id);}
 @Transactional public Map<String,Object> cancel(UUID user,UUID id){var a=recruitment.current(user);var rows=db.queryForList("SELECT * FROM partner_office_appointments WHERE id=? AND application_id=? FOR UPDATE",id,a.id());if(rows.isEmpty())throw RecruitmentService.invalid("Không tìm thấy lịch hẹn.");if("CANCELLED".equals(rows.getFirst().get("status")))return rows.getFirst();if(!"BOOKED".equals(rows.getFirst().get("status")))throw RecruitmentService.invalid("Lịch đã check-in không thể hủy.");db.update("UPDATE partner_office_appointments SET status='CANCELLED' WHERE id=?",id);recruitment.audit(user,a.id(),"OFFICE_APPOINTMENT_CANCELLED",null,null,"");return db.queryForMap("SELECT * FROM partner_office_appointments WHERE id=?",id);}
 public List<Map<String,Object>> checklist(){return db.queryForList("SELECT * FROM partner_document_checklist WHERE active=true ORDER BY label,id");}
 @Transactional public List<Map<String,Object>> receipts(UUID user){var a=recruitment.current(user);return db.queryForList("SELECT id,appointment_id,originals_returned,complete,notes,checklist,received_at FROM partner_document_receipts WHERE application_id=? ORDER BY received_at DESC",a.id());}
 @Transactional public Map<String,Object> saveChecklist(UUID actor,UUID id,ChecklistWrite w){if(db.queryForObject("SELECT COUNT(*) FROM partner_document_checklist WHERE id=?",Integer.class,id)>0)db.update("UPDATE partner_document_checklist SET label=?,required=?,active=? WHERE id=?",w.label(),w.required(),w.active(),id);else db.update("INSERT INTO partner_document_checklist VALUES(?,?,?,?)",id,w.label(),w.required(),w.active());recruitment.audit(actor,null,"DOCUMENT_CHECKLIST_UPDATED",null,null,"Mục "+id);return db.queryForMap("SELECT * FROM partner_document_checklist WHERE id=?",id);}
 @Transactional public Map<String,Object> checkin(UUID actor,UUID id,Checkin w){lockApplicant(id);var rows=db.queryForList("SELECT * FROM partner_office_appointments WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw RecruitmentService.invalid("Không tìm thấy lịch.");var a=rows.getFirst();if(!w.code().equals(a.get("checkin_code")))throw RecruitmentService.invalid("Mã check-in không đúng.");if("CHECKED_IN".equals(a.get("status")))return a;if(!"BOOKED".equals(a.get("status")))throw RecruitmentService.invalid("Lịch không còn hợp lệ.");db.update("UPDATE partner_office_appointments SET status='CHECKED_IN',checked_in_at=? WHERE id=?",Timestamp.from(Instant.now()),id);db.update("UPDATE partner_applications SET appointment_checked_in=true,version=version+1 WHERE id=?",a.get("application_id"));recruitment.audit(actor,(UUID)a.get("application_id"),"OFFICE_CHECKED_IN",null,null,"");review.notify((UUID)a.get("application_id"),"Chào mừng Partner đến văn phòng!","Bạn đã check-in thành công. Vui lòng gặp nhân viên để đối chiếu giấy tờ gốc và hoàn tất thủ tục nhận đồng phục. Cảm ơn bạn đã đồng hành cùng TaskLy!");return db.queryForMap("SELECT * FROM partner_office_appointments WHERE id=?",id);}
 @Transactional public Map<String,Object> receive(UUID actor,UUID id,Receive w){lockApplicant(id);var rows=db.queryForList("SELECT * FROM partner_office_appointments WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw RecruitmentService.invalid("Không tìm thấy lịch.");var previous=db.queryForList("SELECT * FROM partner_document_receipts WHERE appointment_id=?",id);if(!previous.isEmpty()){var saved=previous.getFirst();var savedChecklist=json.readValue((String)saved.get("checklist"),new tools.jackson.core.type.TypeReference<Map<UUID,Boolean>>(){});if(!Objects.equals(saved.get("notes"),w.notes())||!Objects.equals(saved.get("originals_returned"),w.originalsReturned())||!savedChecklist.equals(w.checklist()))throw RecruitmentService.conflict();return saved;}if(!"CHECKED_IN".equals(rows.getFirst().get("status")))throw RecruitmentService.invalid("Check-in trước khi tiếp nhận hồ sơ.");if(!w.originalsReturned())throw RecruitmentService.invalid("Phải đối chiếu và trả lại giấy tờ gốc ngay.");var appId=(UUID)rows.getFirst().get("application_id");var appUser=db.queryForObject("SELECT user_id FROM partner_applications WHERE id=?",UUID.class,appId);recruitment.current(appUser);var list=checklist();if(list.isEmpty())throw RecruitmentService.invalid("Chưa cấu hình checklist hồ sơ.");if(w.checklist().keySet().stream().anyMatch(key->list.stream().noneMatch(item->item.get("id").equals(key))))throw RecruitmentService.invalid("Checklist chứa mục không hợp lệ.");boolean complete=list.stream().filter(item->Boolean.TRUE.equals(item.get("required"))).allMatch(item->Boolean.TRUE.equals(w.checklist().get(item.get("id"))));var receipt=UUID.randomUUID();var now=Timestamp.from(Instant.now());db.update("INSERT INTO partner_document_receipts VALUES(?,?,?,?,?,?,?,?,?)",receipt,appId,id,actor,true,complete,w.notes(),json.writeValueAsString(w.checklist()),now);db.update("UPDATE partner_applications SET documents_valid=?,documents_received_at=?,status=?,reason=?,version=version+1,updated_at=? WHERE id=?",complete,complete?now:null,complete?"DOCUMENTS_RECEIVED":"ACTION_REQUIRED",complete?"":"Bổ sung các giấy tờ thiếu trong biên nhận.",now,appId);db.update("UPDATE partner_office_appointments SET status='COMPLETED' WHERE id=?",id);recruitment.audit(actor,appId,"PHYSICAL_DOCUMENTS_RECEIVED",null,complete?"DOCUMENTS_RECEIVED":"ACTION_REQUIRED","Biên nhận "+receipt);review.notify(appId,"Biên nhận hồ sơ",complete?"Đã nhận đủ hồ sơ hợp lệ.":"Hồ sơ còn thiếu. Đặt lại lịch để bổ sung.");return db.queryForMap("SELECT * FROM partner_document_receipts WHERE id=?",receipt);}
}
